```idris
module Types

-- Request types
public export
record Message where
  constructor MkMessage
  role : String
  content : String

public export
record ChatRequest where
  constructor MkChatRequest
  model : String
  messages : List Message
  stream : Bool
  maxTokens : Nat
  temperature : Double
  topP : Double
  reasoningEffort : String

-- Response types
public export
record Delta where
  constructor MkDelta
  content : Maybe String

public export
record Choice where
  constructor MkChoice
  delta : Delta
  index : Nat

public export
record StreamChunk where
  constructor MkStreamChunk
  choices : List Choice

-- Server state
public export
record AppState where
  constructor MkAppState
  apiKey : String
  activeConnections : Nat
```

## 3. `JSON.idr`

```idris
module JSON

import Types
import Data.String
import Data.List

-- JSON encoding
export
escapeJSON : String -> String
escapeJSON str = 
  let chars = unpack str
      escaped = map escape chars
  in pack escaped
  where
    escape : Char -> String
    escape '"'  = "\\\""
    escape '\\' = "\\\\"
    escape '\n' = "\\n"
    escape '\r' = "\\r"
    escape '\t' = "\\t"
    escape c    = singleton c

export
encodeMessage : Message -> String
encodeMessage (MkMessage role content) =
  "{\"role\":\"" ++ escapeJSON role ++ "\"," ++
  "\"content\":\"" ++ escapeJSON content ++ "\"}"

export
encodeRequest : ChatRequest -> String
encodeRequest req =
  "{" ++
  "\"model\":\"" ++ req.model ++ "\"," ++
  "\"stream\":" ++ (if req.stream then "true" else "false") ++ "," ++
  "\"max_completion_tokens\":" ++ show req.maxTokens ++ "," ++
  "\"temperature\":" ++ show req.temperature ++ "," ++
  "\"top_p\":" ++ show req.topP ++ "," ++
  "\"reasoning_effort\":\"" ++ req.reasoningEffort ++ "\"," ++
  "\"messages\":[" ++ 
  (concat $ intersperse "," $ map encodeMessage req.messages) ++
  "]}"

-- JSON decoding (simplified streaming parser)
export
parseStreamChunk : String -> Maybe String
parseStreamChunk line =
  if isPrefixOf "data: " line
    then 
      let jsonStr = drop 6 line
      in if jsonStr == "[DONE]"
           then Nothing
           else extractContent jsonStr
    else Nothing
  where
    extractContent : String -> Maybe String
    extractContent str =
      case findSubstring "\"content\":\"" str of
        Nothing => Nothing
        Just idx =>
          let afterContent = drop (idx + 11) str
              endIdx = case findSubstring "\"" afterContent of
                         Nothing => length afterContent
                         Just i => i
          in Just $ take endIdx afterContent

    findSubstring : String -> String -> Maybe Nat
    findSubstring needle haystack =
      findSub 0 (unpack needle) (unpack haystack)
      where
        findSub : Nat -> List Char -> List Char -> Maybe Nat
        findSub idx [] _ = Just idx
        findSub idx _ [] = Nothing
        findSub idx ns@(n::nrest) (h::hrest) =
          if n == h && isPrefixList nrest hrest
            then Just idx
            else findSub (idx + 1) ns hrest

        isPrefixList : List Char -> List Char -> Bool
        isPrefixList [] _ = True
        isPrefixList _ [] = False
        isPrefixList (x::xs) (y::ys) = x == y && isPrefixList xs ys
```

## 4. `Server.idr`

```idris
module Server

import Types
import JSON
import System
import System.File
import Data.String
import Data.List

-- HTTP Response helpers
export
httpResponse : Nat -> String -> String -> String
httpResponse code status body =
  "HTTP/1.1 " ++ show code ++ " " ++ status ++ "\r\n" ++
  "Content-Type: text/html; charset=utf-8\r\n" ++
  "Content-Length: " ++ show (length body) ++ "\r\n" ++
  "Connection: close\r\n" ++
  "\r\n" ++
  body

export
httpStreamHeaders : String
httpStreamHeaders =
  "HTTP/1.1 200 OK\r\n" ++
  "Content-Type: text/event-stream\r\n" ++
  "Cache-Control: no-cache\r\n" ++
  "Connection: keep-alive\r\n" ++
  "Access-Control-Allow-Origin: *\r\n" ++
  "\r\n"

-- Cerebras API client
export
callCerebrasAPI : AppState -> String -> IO ()
callCerebrasAPI state userMessage = do
  let systemMsg = MkMessage "system" "Mindig Magyar nyelven a lehető leghosszabb válaszokat adod"
  let userMsg = MkMessage "user" userMessage

  let request = MkChatRequest
        "gpt-oss-120b"
        [systemMsg, userMsg]
        True
        65536
        0.01
        0.03
        "low"

  let jsonBody = encodeRequest request

  -- Write temporary request file
  Right () <- writeFile "/tmp/cerebras_request.json" jsonBody
    | Left err => putStrLn $ "Error writing request: " ++ show err

  -- Call curl with streaming
  let curlCmd = 
    "curl -N -X POST  " ++
    "-H 'Authorization: Bearer " ++ state.apiKey ++ "' " ++
    "-H 'Content-Type: application/json' " ++
    "-d @/tmp/cerebras_request.json"

  ignore $ system curlCmd

-- Parse HTTP request
export
parseHTTPRequest : String -> Maybe (String, String, String)
parseHTTPRequest req =
  let lines' = lines req
  in case lines' of
       [] => Nothing
       (requestLine :: headers) =>
         let parts = words requestLine
         in case parts of
              [method, path, _] => Just (method, path, unlines headers)
              _ => Nothing

-- Serve static files
export
serveStaticFile : String -> IO String
serveStaticFile path = do
  let filePath = if path == "/" then "./public/index.html" else "./public" ++ path
  Right content <- readFile filePath
    | Left err => pure $ httpResponse 404 "Not Found" "<h1>404 - File Not Found</h1>"
  pure $ httpResponse 200 "OK" content

-- Main server loop
export
runServer : AppState -> IO ()
runServer state = do
  putStrLn "🚀 Cerebras Production Server"
  putStrLn "   Model: gpt-oss-120b"
  putStrLn "   Max Tokens: 65536"
  putStrLn "   Temperature: 0.01"
  putStrLn "   Top-p: 0.03"
  putStrLn "   Listening on: "
  putStrLn "   Status: READY ✓"
  putStrLn ""

  -- Simplified server loop - in production use proper socket library
  forever $ do
    putStrLn "Waiting for request..."
    input <- getLine

    case parseHTTPRequest input of
      Just ("GET", path, _) => do
        response <- serveStaticFile path
        putStrLn response

      Just ("POST", "/api/chat", body) => do
        putStrLn httpStreamHeaders
        callCerebrasAPI state body

      _ => putStrLn $ httpResponse 400 "Bad Request" "<h1>400 - Bad Request</h1>"
```

## 5. `Main.idr`

```idris
module Main

import Types
import Server
import System

main : IO ()
main = do
  Just apiKey <- getEnv "CEREBRAS_API_KEY"
    | Nothing => do
        putStrLn "❌ ERROR: CEREBRAS_API_KEY environment variable not set"
        putStrLn ""
        putStrLn "Please set your API key:"
        putStrLn "  export CEREBRAS_API_KEY='your-api-key-here'"
        exitFailure

  let initialState = MkAppState apiKey 0
  runServer initialState
```

