<body>
    <div class="app-container">
        <!-- Header -->
        <header class="header">
            <div class="logo">
                <i class="fas fa-brain"></i>
                <span>Cerebras GPT-OSS-120B</span>
            </div>
            <div class="status-badge">
                <div class="status-dot"></div>
                <span id="statusText">Production Ready</span>
            </div>
        </header>

        <!-- Chat Area -->
        <div class="chat-container" id="chatContainer">
            <!-- Messages will be inserted here -->
        </div>

        <!-- Input Area -->
        <div class="input-container">
            <div class="input-wrapper">
                <textarea 
                    id="userInput" 
                    placeholder="Írj egy üzenetet... (Shift+Enter új sor)" 
                    rows="1"
                ></textarea>
                <button id="sendBtn">
                    <i class="fas fa-paper-plane"></i>
                    Küldés
                </button>
            </div>
        </div>

        <!-- Config Panel -->
        <div class="config-panel">
            <div class="config-item">
                <i class="fas fa-sliders-h"></i>
                Max Tokens: <span class="config-value">65,536</span>
            </div>
            <div class="config-item">
                <i class="fas fa-thermometer-half"></i>
                Temperature: <span class="config-value">0.01</span>
            </div>
            <div class="config-item">
                <i class="fas fa-chart-line"></i>
                Top-p: <span class="config-value">0.03</span>
            </div>
            <div class="config-item">
                <i class="fas fa-bolt"></i>
                Reasoning: <span class="config-value">Low</span>
            </div>
            <div class="config-item">
                <i class="fas fa-microchip"></i>
                Backend: <span class="config-value">Idris 2</span>
            </div>
        </div>
    </div>

    <script>
        const API_ENDPOINT = '';
        const API_KEY = 'YOUR_CEREBRAS_API_KEY_HERE'; // IMPORTANT: Replace with actual key

        const chatContainer = document.getElementById('chatContainer');
        const userInput = document.getElementById('userInput');
        const sendBtn = document.getElementById('sendBtn');
        const statusText = document.getElementById('statusText');

        let isProcessing = false;
        let conversationHistory = [];

        // Auto-resize textarea
        userInput.addEventListener('input', function() {
            this.style.height = 'auto';
            this.style.height = Math.min(this.scrollHeight, 200) + 'px';
        });

        // Keyboard shortcuts
        userInput.addEventListener('keydown', function(e) {
            if (e.key === 'Enter' && !e.shiftKey) {
                e.preventDefault();
                sendMessage();
            }
        });

        // Send message
        async function sendMessage() {
            const message = userInput.value.trim();
            if (!message || isProcessing) return;

            isProcessing = true;
            updateStatus('Processing...', 'warning');

            // Add user message
            addMessage('user', message);
            conversationHistory.push({
                role: 'user',
                content: message
            });

            // Clear input
            userInput.value = '';
            userInput.style.height = 'auto';

            // Disable controls
            userInput.disabled = true;
            sendBtn.disabled = true;

            // Create assistant message container
            const assistantMsgId = 'msg-' + Date.now();
            addMessage('assistant', '', assistantMsgId, true);

            try {
                const response = await fetch(API_ENDPOINT, {
                    method: 'POST',
                    headers: {
                        'Authorization': `Bearer ${API_KEY}`,
                        'Content-Type': 'application/json'
                    },
                    body: JSON.stringify({
                        model: 'gpt-oss-120b',
                        stream: true,
                        max_completion_tokens: 65536,
                        temperature: 0.01,
                        top_p: 0.03,
                        reasoning_effort: 'low',
                        messages: [
                            {
                                role: 'system',
                                content: 'Mindig Magyar nyelven a lehető leghosszabb válaszokat adod'
                            },
                            ...conversationHistory
                        ]
                    })
                });

                if (!response.ok) {
                    throw new Error(`HTTP error! status: ${response.status}`);
                }

                // Process stream
                const reader = response.body.getReader();
                const decoder = new TextDecoder();
                let buffer = '';
                let fullResponse = '';

                const msgElement = document.getElementById(assistantMsgId);
                const contentElement = msgElement.querySelector('.message-content');

                // Remove typing indicator
                const typingIndicator = contentElement.querySelector('.typing-indicator');
                if (typingIndicator) typingIndicator.remove();

                while (true) {
                    const { done, value } = await reader.read();
                    if (done) break;

                    buffer += decoder.decode(value, { stream: true });
                    const lines = buffer.split('\n');
                    buffer = lines.pop() || '';

                    for (const line of lines) {
                        if (line.startsWith('data: ')) {
                            const data = line.slice(6).trim();
                            if (data === '[DONE]') continue;

                            try {
                                const json = JSON.parse(data);
                                const content = json.choices?.[0]?.delta?.content;

                                if (content) {
                                    fullResponse += content;
                                    contentElement.textContent = fullResponse;
                                    chatContainer.scrollTop = chatContainer.scrollHeight;
                                }
                            } catch (e) {
                                console.error('JSON parse error:', e, 'Line:', data);
                            }
                        }
                    }
                }

                // Save assistant response
                conversationHistory.push({
                    role: 'assistant',
                    content: fullResponse
                });

                updateStatus('Ready', 'success');

            } catch (error) {
                console.error('Error:', error);
                const msgElement = document.getElementById(assistantMsgId);
                const contentElement = msgElement.querySelector('.message-content');
                contentElement.innerHTML = `<span style="color: var(--error);">❌ Hiba történt: ${error.message}</span>`;
                updateStatus('Error', 'error');
            } finally {
                isProcessing = false;
                userInput.disabled = false;
                sendBtn.disabled = false;
                userInput.focus();
            }
        }

        // Add message to chat
        function addMessage(role, content, id = null, showTyping = false) {
            const msgDiv = document.createElement('div');
            msgDiv.className = `message ${role}`;
            if (id) msgDiv.id = id;

            const avatar = document.createElement('div');
            avatar.className = 'message-avatar';
            avatar.innerHTML = role === 'user' ? '<i class="fas fa-user"></i>' : '<i class="fas fa-brain"></i>';

            const contentDiv = document.createElement('div');
            contentDiv.className = 'message-content';

            if (showTyping) {
                contentDiv.innerHTML = `
                    <div class="typing-indicator">
                        <div class="typing-dot"></div>
                        <div class="typing-dot"></div>
                        <div class="typing-dot"></div>
                    </div>
                `;
            } else {
                contentDiv.textContent = content;
            }

            msgDiv.appendChild(avatar);
            msgDiv.appendChild(contentDiv);
            chatContainer.appendChild(msgDiv);
            chatContainer.scrollTop = chatContainer.scrollHeight;
        }

        // Update status
        function updateStatus(text, type) {
            statusText.textContent = text;
            const dot = document.querySelector('.status-dot');

            if (type === 'success') {
                dot.style.background = 'var(--success)';
            } else if (type === 'warning') {
                dot.style.background = 'var(--warning)';
            } else if (type === 'error') {
                dot.style.background = 'var(--error)';
            }
        }

        // Initialize
        updateStatus('Production Ready', 'success');
        userInput.focus();
    </script>
</body>
