```html
    <!-- Main Application JavaScript -->
    <script>
        'use strict';

        // ============================================
        // CONFIGURATION
        // ============================================
        const CONFIG = {
            API_ENDPOINT: '',
            API_KEY: 'YOUR_CEREBRAS_API_KEY_HERE', // REPLACE WITH YOUR ACTUAL KEY
            MODEL: 'gpt-oss-120b',
            MAX_TOKENS: 65536,
            TEMPERATURE: 0.01,
            TOP_P: 0.03,
            REASONING_EFFORT: 'low',
            SYSTEM_MESSAGE: 'Mindig Magyar nyelven a lehető leghosszabb válaszokat adod. Részletes, alapos és informatív válaszokat adj, amely kihasználja a rendelkezésre álló token limitet.',
            MAX_INPUT_LENGTH: 10000,
            AUTO_SCROLL_THRESHOLD: 100,
            TYPING_INDICATOR_DELAY: 100
        };

        // ============================================
        // STATE MANAGEMENT
        // ============================================
        const state = {
            isProcessing: false,
            conversationHistory: [],
            messageCount: 0,
            totalTokensEstimate: 0,
            startTime: Date.now()
        };

        // ============================================
        // DOM ELEMENTS
        // ============================================
        const elements = {
            chatContainer: document.getElementById('chatContainer'),
            userInput: document.getElementById('userInput'),
            sendBtn: document.getElementById('sendBtn'),
            clearBtn: document.getElementById('clearBtn'),
            statusBadge: document.getElementById('statusBadge'),
            statusText: document.getElementById('statusText'),
            charCount: document.getElementById('charCount'),
            welcomeMessage: document.getElementById('welcomeMessage'),
            themeToggle: document.getElementById('themeToggle')
        };

        // ============================================
        // UTILITY FUNCTIONS
        // ============================================

        function sanitizeHTML(html) {
            return DOMPurify.sanitize(html, {
                ALLOWED_TAGS: ['p', 'br', 'strong', 'em', 'u', 'code', 'pre', 'h1', 'h2', 'h3', 'h4', 'h5', 'h6', 'ul', 'ol', 'li', 'a', 'blockquote', 'table', 'thead', 'tbody', 'tr', 'th', 'td'],
                ALLOWED_ATTR: ['href', 'title', 'target', 'rel', 'class']
            });
        }

        function formatTimestamp() {
            const now = new Date();
            return now.toLocaleTimeString('hu-HU', { hour: '2-digit', minute: '2-digit' });
        }

        function estimateTokens(text) {
            // Rough estimate: 1 token ≈ 4 characters for Hungarian
            return Math.ceil(text.length / 4);
        }

        function debounce(func, wait) {
            let timeout;
            return function executedFunction(...args) {
                const later = () => {
                    clearTimeout(timeout);
                    func(...args);
                };
                clearTimeout(timeout);
                timeout = setTimeout(later, wait);
            };
        }

        function shouldAutoScroll() {
            const threshold = CONFIG.AUTO_SCROLL_THRESHOLD;
            const position = elements.chatContainer.scrollTop + elements.chatContainer.clientHeight;
            const height = elements.chatContainer.scrollHeight;
            return height - position < threshold;
        }

        function scrollToBottom(smooth = true) {
            elements.chatContainer.scrollTo({
                top: elements.chatContainer.scrollHeight,
                behavior: smooth ? 'smooth' : 'auto'
            });
        }

        // ============================================
        // STATUS MANAGEMENT
        // ============================================

        function updateStatus(text, type = 'success') {
            elements.statusText.textContent = text;
            elements.statusBadge.className = 'status-badge ' + type;
            elements.statusBadge.setAttribute('aria-label', text);
        }

        function setProcessing(processing) {
            state.isProcessing = processing;
            elements.userInput.disabled = processing;
            elements.sendBtn.disabled = processing;

            if (processing) {
                updateStatus('Processing...', 'processing');
                elements.sendBtn.innerHTML = '<i class="fas fa-spinner fa-spin"></i><span>Feldolgozás</span>';
            } else {
                updateStatus('Ready', 'success');
                elements.sendBtn.innerHTML = '<i class="fas fa-paper-plane"></i><span>Küldés</span>';
            }
        }

        // ============================================
        // MESSAGE RENDERING
        // ============================================

        function createMessageElement(role, content, options = {}) {
            const messageDiv = document.createElement('div');
            messageDiv.className = `message ${role}`;
            if (options.id) messageDiv.id = options.id;

            const avatar = document.createElement('div');
            avatar.className = 'message-avatar';
            avatar.innerHTML = role === 'user' 
                ? '<i class="fas fa-user"></i>' 
                : '<i class="fas fa-brain"></i>';

            const contentWrapper = document.createElement('div');
            contentWrapper.className = 'message-content-wrapper';

            const header = document.createElement('div');
            header.className = 'message-header';

            const author = document.createElement('span');
            author.className = 'message-author';
            author.textContent = role === 'user' ? 'Te' : 'Asszisztens';

            const timestamp = document.createElement('span');
            timestamp.className = 'message-timestamp';
            timestamp.textContent = formatTimestamp();

            header.appendChild(author);
            header.appendChild(timestamp);

            const messageContent = document.createElement('div');
            messageContent.className = 'message-content';

            if (options.showTyping) {
                messageContent.innerHTML = `
                    <div class="typing-indicator">
                        <div class="typing-dot"></div>
                        <div class="typing-dot"></div>
                        <div class="typing-dot"></div>
                    </div>
                `;
            } else {
                const rendered = marked.parse(content);
                messageContent.innerHTML = sanitizeHTML(rendered);

                // Highlight code blocks
                messageContent.querySelectorAll('pre code').forEach((block) => {
                    hljs.highlightElement(block);
                });
            }

            contentWrapper.appendChild(header);
            contentWrapper.appendChild(messageContent);
            messageDiv.appendChild(avatar);
            messageDiv.appendChild(contentWrapper);

            return messageDiv;
        }

        function addMessage(role, content, options = {}) {
            if (elements.welcomeMessage) {
                elements.welcomeMessage.remove();
            }

            const messageElement = createMessageElement(role, content, options);
            elements.chatContainer.appendChild(messageElement);

            if (shouldAutoScroll()) {
                scrollToBottom();
            }

            return messageElement;
        }

        function updateMessageContent(messageId, content) {
            const messageElement = document.getElementById(messageId);
            if (!messageElement) return;

            const contentDiv = messageElement.querySelector('.message-content');
            if (!contentDiv) return;

            const typingIndicator = contentDiv.querySelector('.typing-indicator');
            if (typingIndicator) {
                typingIndicator.remove();
            }

            const rendered = marked.parse(content);
            contentDiv.innerHTML = sanitizeHTML(rendered);

            // Highlight code blocks
            contentDiv.querySelectorAll('pre code').forEach((block) => {
                hljs.highlightElement(block);
            });

            if (shouldAutoScroll()) {
                scrollToBottom();
            }
        }

        // ============================================
        // API COMMUNICATION
        // ============================================

        async function sendMessage() {
            const message = elements.userInput.value.trim();
            if (!message || state.isProcessing) return;

            // Validate API key
            if (CONFIG.API_KEY === 'YOUR_CEREBRAS_API_KEY_HERE') {
                alert('Kérlek állítsd be a CEREBRAS_API_KEY-t az index.html fájlban!');
                return;
            }

            setProcessing(true);

            // Add user message
            addMessage('user', message);
            state.conversationHistory.push({
                role: 'user',
                content: message
            });

            // Clear input
            elements.userInput.value = '';
            elements.userInput.style.height = 'auto';
            updateCharCount();

            // Create assistant message container
            const assistantMsgId = 'msg-' + Date.now();
            addMessage('assistant', '', { id: assistantMsgId, showTyping: true });

            try {
                const response = await fetch(CONFIG.API_ENDPOINT, {
                    method: 'POST',
                    headers: {
                        'Authorization': `Bearer ${CONFIG.API_KEY}`,
                        'Content-Type': 'application/json',
                        'Accept': 'text/event-stream'
                    },
                    body: JSON.stringify({
                        model: CONFIG.MODEL,
                        stream: true,
                        max_completion_tokens: CONFIG.MAX_TOKENS,
                        temperature: CONFIG.TEMPERATURE,
                        top_p: CONFIG.TOP_P,
                        reasoning_effort: CONFIG.REASONING_EFFORT,
                        messages: [
                            {
                                role: 'system',
                                content: CONFIG.SYSTEM_MESSAGE
                            },
                            ...state.conversationHistory
                        ]
                    })
                });

                if (!response.ok) {
                    throw new Error(`HTTP error! status: ${response.status}`);
                }

                // Process stream
                const reader = response.body.getReader();
                const decoder = new TextDecoder('utf-8');
                let buffer = '';
                let fullResponse = '';

                while (true) {
                    const { done, value } = await reader.read();
                    if (done) break;

                    buffer += decoder.decode(value, { stream: true });
                    const lines = buffer.split('\n');
                    buffer = lines.pop() || '';

                    for (const line of lines) {
                        if (line.startsWith('data: ')) {
                            const data = line.slice(6).trim();
                            if (data === '[DONE]') continue;

                            try {
                                const json = JSON.parse(data);
                                const content = json.choices?.[0]?.delta?.content;

                                if (content) {
                                    fullResponse += content;
                                    updateMessageContent(assistantMsgId, fullResponse);
                                }
                            } catch (e) {
                                console.error('JSON parse error:', e, 'Line:', data);
                            }
                        }
                    }
                }

                // Save assistant response
                state.conversationHistory.push({
                    role: 'assistant',
                    content: fullResponse
                });

                state.messageCount++;
                state.totalTokensEstimate += estimateTokens(fullResponse);

                updateStatus('Ready', 'success');

            } catch (error) {
                console.error('Error:', error);
                updateMessageContent(assistantMsgId, `❌ **Hiba történt:** ${error.message}\n\nKérlek ellenőrizd:\n- Az API kulcs helyes-e\n- Van-e internet kapcsolat\n- A Cerebras API elérhető-e`);
                updateStatus('Error', 'error');
            } finally {
                setProcessing(false);
                elements.userInput.focus();
            }
        }

        // ============================================
        // INPUT HANDLING
        // ============================================

        function autoResizeTextarea() {
            elements.userInput.style.height = 'auto';
            elements.userInput.style.height = Math.min(elements.userInput.scrollHeight, 200) + 'px';
        }

        function updateCharCount() {
            const length = elements.userInput.value.length;
            elements.charCount.textContent = `${length} / ${CONFIG.MAX_INPUT_LENGTH}`;

            if (length > CONFIG.MAX_INPUT_LENGTH * 0.9) {
                elements.charCount.style.color = 'var(--warning)';
            } else {
                elements.charCount.style.color = 'var(--text-dim)';
            }
        }

        function clearConversation() {
            if (!confirm('Biztosan törölni szeretnéd a teljes beszélgetést?')) {
                return;
            }

            state.conversationHistory = [];
            state.messageCount = 0;
            state.totalTokensEstimate = 0;

            elements.chatContainer.innerHTML = `
                <div class="welcome-message" id="welcomeMessage">
                    <div class="welcome-icon" aria-hidden="true">
                        <i class="fas fa-comments"></i>
                    </div>
                    <h1 class="welcome-title">Üdvözöl a Cerebras GPT-OSS-120B</h1>
                    <p class="welcome-description">
                        Ultra-gyors mesterséges intelligencia motor 65,536 token kontextussal.
                        Idris 2 backend biztosítja a maximális teljesítményt és típusbiztonságot.
                    </p>
                    <div class="welcome-features">
                        <div class="welcome-feature">
                            <div class="welcome-feature-icon"><i class="fas fa-bolt"></i></div>
                            <div class="welcome-feature-title">Villámgyors</div>
                            <div class="welcome-feature-desc">Alacsony latencia streaming</div>
                        </div>
                        <div class="welcome-feature">
                            <div class="welcome-feature-icon"><i class="fas fa-infinity"></i></div>
                            <div class="welcome-feature-title">65K Token</div>
                            <div class="welcome-feature-desc">Óriási kontextus ablak</div>
                        </div>
                        <div class="welcome-feature">
                            <div class="welcome-feature-icon"><i class="fas fa-shield-alt"></i></div>
                            <div class="welcome-feature-title">Biztonságos</div>
                            <div class="welcome-feature-desc">Típusbiztos Idris 2 backend</div>
                        </div>
                        <div class="welcome-feature">
                            <div class="welcome-feature-icon"><i class="fas fa-language"></i></div>
                            <div class="welcome-feature-title">Magyar nyelv</div>
                            <div class="welcome-feature-desc">Optimalizált magyar válaszok</div>
                        </div>
                    </div>
                </div>
            `;

            elements.welcomeMessage = document.getElementById('welcomeMessage');
            updateStatus('Conversation cleared', 'success');
        }

        // ============================================
        // EVENT LISTENERS
        // ============================================

        elements.userInput.addEventListener('input', () => {
            autoResizeTextarea();
            updateCharCount();
        });

        elements.userInput.addEventListener('keydown', (e) => {
            if (e.key === 'Enter' && !e.shiftKey) {
                e.preventDefault();
                sendMessage();
            }
        });

        elements.sendBtn.addEventListener('click', sendMessage);
        elements.clearBtn.addEventListener('click', clearConversation);

        elements.themeToggle.addEventListener('click', () => {
            // Theme toggle functionality (can be extended)
            document.body.classList.toggle('dark-theme');
        });

        // ============================================
        // KEYBOARD SHORTCUTS
        // ============================================

        document.addEventListener('keydown', (e) => {
            // Ctrl/Cmd + K: Focus input
            if ((e.ctrlKey || e.metaKey) && e.key === 'k') {
                e.preventDefault();
                elements.userInput.focus();
            }

            // Ctrl/Cmd + L: Clear conversation
            if ((e.ctrlKey || e.metaKey) && e.key === 'l') {
                e.preventDefault();
                clearConversation();
            }

            // Escape: Clear input
            if (e.key === 'Escape') {
                elements.userInput.value = '';
                autoResizeTextarea();
                updateCharCount();
            }
        });

        // ============================================
        // INITIALIZATION
        // ============================================

        function initialize() {
            console.log('%c🚀 Cerebras GPT-OSS-120B Production Interface', 'color: #e51284; font-size: 20px; font-weight: bold;');
            console.log('%cPowered by Idris 2 Backend', 'color: #0077ff; font-size: 14px;');
            console.log('%cVersion 1.0.0', 'color: #10b981; font-size: 12px;');

            // Configure marked.js
            marked.setOptions({
                breaks: true,
                gfm: true,
                headerIds: false,
                mangle: false
            });

            // Initialize highlight.js
            hljs.configure({
                languages: ['javascript', 'python', 'java', 'cpp', 'html', 'css', 'json', 'xml', 'bash', 'sql', 'typescript', 'rust', 'go', 'idris']
            });

            // Set initial status
            updateStatus('Production Ready', 'success');
            updateCharCount();

            // Focus input
            elements.userInput.focus();

            // Check API key
            if (CONFIG.API_KEY === 'YOUR_CEREBRAS_API_KEY_HERE') {
                console.warn('%c⚠️ API KEY NOT SET', 'color: #f59e0b; font-size: 14px; font-weight: bold;');
                console.log('Please set your CEREBRAS_API_KEY in the CONFIG object.');
            }

            console.log('%c✅ Application initialized successfully', 'color: #10b981; font-size: 12px;');
        }

        // ============================================
        // START APPLICATION
        // ============================================

        if (document.readyState === 'loading') {
            document.addEventListener('DOMContentLoaded', initialize);
        } else {
            initialize();
        }

        // Service Worker registration (optional, for PWA)
        if ('serviceWorker' in navigator) {
            window.addEventListener('load', () => {
